    .li      s3, #0x5
    atom.max.u.w s4, [s7], s3
    .assert_eq s4, #0xfffffff0, #107
    s.ld.d   s6, [s1, #0]
    .assert_eq s6, #0xfffffff05a5a5a5a, #108

    // atom.cas: swaps only on a match, and returns the old value either way
    .li      s2, #0x7
    s.st.d   [s1, #0], s2
    .li      s3, #0x7
    .li      s8, #0x63
    atom.cas.d s4, [s1], s3, s8
    .assert_eq s4, #0x7, #109
    s.ld.d   s6, [s1, #0]
    .assert_eq s6, #0x63, #110
    .li      s2, #0x7
    s.st.d   [s1, #0], s2
    .li      s3, #0x8
    .li      s8, #0x63
    atom.cas.d s4, [s1], s3, s8
    .assert_eq s4, #0x7, #111
    s.ld.d   s6, [s1, #0]
    .assert_eq s6, #0x7, #112

    // atom.ld returns the word and leaves it; atom.st replaces it
    .li      s2, #0xbadc0dedeadbeef
    s.st.d   [s1, #0], s2
    atom.ld.d.acquire s4, [s1]
    .assert_eq s4, #0x0badc0dedeadbeef, #113
    s.ld.d   s6, [s1, #0]
    .assert_eq s6, #0x0badc0dedeadbeef, #114   // atom.ld is not a write
    .li      s3, #0x1234
    atom.st.d.release [s1], s3
    s.ld.d   s6, [s1, #0]
    .assert_eq s6, #0x1234, #115

    // A fence between a store and an atomic changes no value, which is the
    // point: it must be a no-op on the data and an ordering point on the
    // machine. What is checked here is that it retires at all.
    .li      s2, #0x5
    s.st.d   [s1, #0], s2
    fence.release.device
    .li      s3, #0x3
    atom.add.d.acquire.device s4, [s1], s3
    .assert_eq s4, #5, #116
    fence.acq_rel.device
    s.ld.d   s6, [s1, #0]
    .assert_eq s6, #8, #117

    exit

